COMMENT ON COLUMN "query_cache"."cache_key" IS 'Mã băm SHA-256 khóa đệm tổng hợp';

COMMENT ON COLUMN "query_cache"."question" IS 'Nội dung câu hỏi nguyên bản của người dùng';

COMMENT ON COLUMN "query_cache"."normalized_question" IS 'Nội dung câu hỏi đã qua xử lý chuẩn hóa chữ hoa/thường, dấu';

COMMENT ON COLUMN "query_cache"."book_codes" IS 'Bộ lọc danh sách sách yêu cầu truy vấn (ví dụ NPL,BD)';

COMMENT ON COLUMN "query_cache"."model_name" IS 'Tên mô hình LLM sinh phản hồi';

COMMENT ON COLUMN "query_cache"."prompt_hash" IS 'Mã băm của template system prompt';

COMMENT ON COLUMN "query_cache"."index_version" IS 'Phiên bản chỉ mục tri thức tại thời điểm cache';

COMMENT ON COLUMN "query_cache"."status" IS 'Trạng thái kết quả: success, no_context, error';

COMMENT ON COLUMN "query_cache"."response_json" IS 'Chuỗi JSON chứa kết quả phản hồi hoàn chỉnh kèm trích dẫn';

COMMENT ON COLUMN "query_cache"."hit_count" IS 'Số lần truy vấn tái sử dụng kết quả trong cache';

COMMENT ON COLUMN "query_cache"."created_at" IS 'Thời điểm tạo bản ghi cache';

COMMENT ON COLUMN "query_cache"."last_hit_at" IS 'Thời điểm có lượt truy vấn trúng cache gần nhất';

COMMENT ON TABLE "horoscope_cache" IS 'Lưu đệm các bài luận giải lá số hoàn chỉnh theo năm xem, bảng Tứ Hóa và hash lá số đầu vào nhằm tiết kiệm chi phí gọi LLM.';

COMMENT ON COLUMN "horoscope_cache"."cache_key" IS 'Mã băm duy nhất xác định bài luận lá số';

COMMENT ON COLUMN "horoscope_cache"."payload_hash" IS 'Mã băm tổng hợp dữ liệu lá số đầu vào và bảng Tứ Hóa';

COMMENT ON COLUMN "horoscope_cache"."target_year" IS 'Năm xem hạn luận giải';

COMMENT ON COLUMN "horoscope_cache"."model_name" IS 'Mô hình AI đã thực hiện luận giải';

COMMENT ON COLUMN "horoscope_cache"."response_json" IS 'Nội dung bài luận JSON có cấu trúc 3 tầng';

COMMENT ON COLUMN "horoscope_cache"."hit_count" IS 'Số lần tái sử dụng bài luận';

COMMENT ON COLUMN "horoscope_cache"."created_at" IS 'Thời điểm tạo cache';

COMMENT ON COLUMN "horoscope_cache"."last_hit_at" IS 'Thời điểm bài luận được truy xuất gần nhất';

COMMENT ON TABLE "validation_cases" IS 'Hồ sơ ca nghiệm lý lá số ẩn danh (Journal T8), không lưu thông tin ngày giờ sinh hay danh tính cá nhân nhằm bảo vệ quyền riêng tư.';

COMMENT ON COLUMN "validation_cases"."case_id" IS 'Mã hồ sơ ca nghiệm lý định dạng TV-YYYY-NNN';

COMMENT ON COLUMN "validation_cases"."chart_snapshot" IS 'Bản chụp cấu trúc 12 cung, danh sách sao và các facts có trích dẫn nguồn';

COMMENT ON COLUMN "validation_cases"."input_confidence" IS 'Độ tin cậy của giờ sinh đầu vào (A: rất chuẩn xác, B: khoảng 1 giờ, C: chỉ biết buổi, D: không chắc chắn)';

COMMENT ON COLUMN "validation_cases"."created_at" IS 'Thời điểm tạo hồ sơ ca nghiệm lý';

COMMENT ON TABLE "predictions" IS 'Lưu trữ các kết luận dự đoán có thể kiểm chứng được, ghi nhận trước khi sự kiện thực tế diễn ra, hỗ trợ quản lý lịch sử chỉnh sửa.';

COMMENT ON COLUMN "predictions"."prediction_id" IS 'Mã dự đoán duy nhất';

COMMENT ON COLUMN "predictions"."case_id" IS 'Mã ca nghiệm lý tương ứng';

COMMENT ON COLUMN "predictions"."noi_dung" IS 'Nội dung luận đoán cụ thể, không sử dụng tỷ lệ phần trăm tùy tiện';

COMMENT ON COLUMN "predictions"."khoa_thoi_gian" IS 'Khoảng thời gian ứng nghiệm (năm cụ thể hoặc khoảng năm đại vận, ví dụ 2026 hoặc 2026-2035)';

COMMENT ON COLUMN "predictions"."muc_tin_cay" IS 'Mức độ tin cậy của dự đoán: rat_manh, manh, trung_binh, yeu';

COMMENT ON COLUMN "predictions"."loai_ket_luan" IS 'Loại kết luận: cau_truc (tính cách/cơ địa) hoặc thoi_diem (hạn cụ thể)';

COMMENT ON COLUMN "predictions"."chung_cu_ids" IS 'Danh sách mã chứng cứ facts hỗ trợ dự đoán (dạng JSON list)';

COMMENT ON COLUMN "predictions"."phan_chung" IS 'Dữ kiện hoặc yếu tố triệt tiêu/hóa giải có thể làm sai lệch dự đoán';

COMMENT ON COLUMN "predictions"."supersedes" IS 'Mã dự đoán cũ mà bản ghi này thay thế (trong trường hợp đính chính)';

COMMENT ON COLUMN "predictions"."revision_reason" IS 'Lý do thực hiện chỉnh sửa hoặc thay thế dự đoán';

COMMENT ON COLUMN "predictions"."created_at" IS 'Thời điểm tạo dự đoán ban đầu';

COMMENT ON COLUMN "predictions"."locked_at" IS 'Thời điểm khóa dự đoán trước khi đối chiếu biến cố thực tế';

COMMENT ON TABLE "events" IS 'Ghi nhận sự kiện thực tế trong cuộc đời đương số đã xảy ra để đối chiếu, chấm điểm độ chính xác của dự đoán trước đó.';

COMMENT ON COLUMN "events"."event_id" IS 'Mã định danh sự kiện thực tế';

COMMENT ON COLUMN "events"."case_id" IS 'Mã ca nghiệm lý';

COMMENT ON COLUMN "events"."prediction_id" IS 'Mã dự đoán được đem ra đối chiếu kiểm chứng';

COMMENT ON COLUMN "events"."year" IS 'Năm dương lịch xảy ra sự kiện thực tế';

COMMENT ON COLUMN "events"."category" IS 'Lĩnh vực sự kiện: career, finance, marriage, children, family, health, relocation, other';

COMMENT ON COLUMN "events"."mo_ta" IS 'Mô tả chi tiết biến cố đã diễn ra ngoài đời thực';

COMMENT ON COLUMN "events"."prediction_result" IS 'Kết quả đánh giá đối soát: clear_match (khớp hoàn toàn), partial_match (khớp một phần), no_match (không khớp), not_verifiable (không thể kiểm chứng)';

COMMENT ON COLUMN "events"."revealed_at" IS 'Thời điểm cung cấp dữ liệu thực tế';

